<?php
require 'config.php';require 'includes/functions.php';require_login();$user=current_user();$pageTitle='My listings';$activePage='my-listings';
$s=$pdo->prepare("SELECT l.id,l.quantity,l.price,l.note,l.views,l.created_at,c.name AS crop_name,un.name AS unit_name,r.name AS region_name,lt.name AS listing_type,ls.name AS status_name FROM listings l JOIN crops c ON c.id=l.crop_id JOIN units un ON un.id=l.unit_id JOIN regions r ON r.id=l.region_id JOIN listing_types lt ON lt.id=l.listing_type_id JOIN listing_statuses ls ON ls.id=l.status_id WHERE l.user_id=? ORDER BY l.created_at DESC");$s->execute([$user['id']]);$listings=$s->fetchAll();require 'includes/header.php'; ?>
<section class="block top-space"><p class="eyebrow">YOUR ACCOUNT</p><h1>My listings</h1><p class="sub-small">Manage your active, sold and closed listings.</p></section><section class="block"><div class="grid"><?php if(!$listings): ?><div class="empty">You haven't posted anything yet. <a href="post.php">Post your first listing</a>.</div><?php else: foreach($listings as $l): ?><div class="card"><div class="card-top"><div class="crop-name"><?= e($l['crop_name']) ?></div><div class="tag <?= e($l['listing_type']) ?>"><?= e(ucfirst($l['status_name'])) ?></div></div><div class="price-row"><?= e(format_money($l['price'])) ?> <span>/ <?= e($l['unit_name']) ?></span></div><div class="meta"><b><?= e((string)$l['quantity']) ?></b> <?= e($l['unit_name']) ?> · <?= e($l['region_name']) ?></div><div class="posted">Posted <?= e(time_ago($l['created_at'])) ?> · <?= (int)$l['views'] ?> views</div><?php if($l['status_name']==='active'): ?><div class="card-actions"><form method="post" action="listing-action.php" data-confirm="Mark this listing as sold?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$l['id'] ?>"><input type="hidden" name="action" value="sold"><button class="btn btn-ghost btn-small" type="submit">Mark sold</button></form><form method="post" action="listing-action.php" data-confirm="Delete this listing? This cannot be undone."><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$l['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger btn-small" type="submit">Delete</button></form></div><?php else: ?><form method="post" action="listing-action.php" data-confirm="Delete this listing? This cannot be undone."><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$l['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger btn-small" type="submit">Delete</button></form><?php endif; ?></div><?php endforeach;endif; ?></div></section>
<?php require 'includes/footer.php'; ?>
